INSERT INTO `ai_ocr_field_mappings` VALUES (1,'barangay_id','full_name','(?:Name|Full Name|Resident Name)[:\\s]*([A-Za-z\\s.,-]+)','{\"required\": true, \"min_length\": 2, \"max_length\": 100}',10,1,'2025-12-02 18:38:18','2025-12-02 18:38:18'),(2,'barangay_id','address','(?:Address|Residence|Location)[:\\s]*([A-Za-z0-9\\s.,#-]+)','{\"required\": true, \"min_length\": 10}',9,1,'2025-12-02 18:38:18','2025-12-02 18:38:18'),(3,'barangay_id','birthdate','(?:Birth|DOB|Date of Birth)[:\\s]*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4})','{\"required\": true, \"date_format\": true}',8,1,'2025-12-02 18:38:18','2025-12-02 18:38:18'),(4,'drivers_license','license_number','(?:License|DL|Driver.?s License)[:\\s]*([A-Z0-9-]+)','{\"required\": true, \"pattern\": \"^[A-Z0-9-]+$\", \"min_length\": 8}',10,1,'2025-12-02 18:38:18','2025-12-02 18:38:18'),(5,'drivers_license','full_name','(?:Name|Full Name)[:\\s]*([A-Za-z\\s.,-]+)','{\"required\": true, \"min_length\": 2, \"max_length\": 100}',9,1,'2025-12-02 18:38:18','2025-12-02 18:38:18'),(6,'passport','passport_number','(?:Passport|PP)[:\\s]*([A-Z0-9]+)','{\"required\": true, \"pattern\": \"^[A-Z0-9]+$\", \"min_length\": 8}',10,1,'2025-12-02 18:38:18','2025-12-02 18:38:18'),(7,'passport','full_name','(?:Name|Full Name)[:\\s]*([A-Za-z\\s.,-]+)','{\"required\": true, \"min_length\": 2, \"max_length\": 100}',9,1,'2025-12-02 18:38:18','2025-12-02 18:38:18'),(8,'barangay_id','full_name','(?:Name|Full Name|Resident Name)[:\\s]*([A-Za-z\\s.,-]+)','{\"required\": true, \"min_length\": 2, \"max_length\": 100}',10,1,'2025-12-02 18:38:46','2025-12-02 18:38:46'),(9,'barangay_id','address','(?:Address|Residence|Location)[:\\s]*([A-Za-z0-9\\s.,#-]+)','{\"required\": true, \"min_length\": 10}',9,1,'2025-12-02 18:38:46','2025-12-02 18:38:46'),(10,'barangay_id','birthdate','(?:Birth|DOB|Date of Birth)[:\\s]*([0-9]{1,2}[/-][0-9]{1,2}[/-][0-9]{2,4})','{\"required\": true, \"date_format\": true}',8,1,'2025-12-02 18:38:46','2025-12-02 18:38:46'),(11,'drivers_license','license_number','(?:License|DL|Driver.?s License)[:\\s]*([A-Z0-9-]+)','{\"required\": true, \"pattern\": \"^[A-Z0-9-]+$\", \"min_length\": 8}',10,1,'2025-12-02 18:38:46','2025-12-02 18:38:46'),(12,'drivers_license','full_name','(?:Name|Full Name)[:\\s]*([A-Za-z\\s.,-]+)','{\"required\": true, \"min_length\": 2, \"max_length\": 100}',9,1,'2025-12-02 18:38:46','2025-12-02 18:38:46'),(13,'passport','passport_number','(?:Passport|PP)[:\\s]*([A-Z0-9]+)','{\"required\": true, \"pattern\": \"^[A-Z0-9]+$\", \"min_length\": 8}',10,1,'2025-12-02 18:38:46','2025-12-02 18:38:46'),(14,'passport','full_name','(?:Name|Full Name)[:\\s]*([A-Za-z\\s.,-]+)','{\"required\": true, \"min_length\": 2, \"max_length\": 100}',9,1,'2025-12-02 18:38:46','2025-12-02 18:38:46');
