INSERT INTO `document_templates` VALUES (1,'Default Barangay Clearance','barangay_clearance',NULL,'{\"title\":\"BARANGAY CLEARANCE\",\"header_text\":\"TO WHOM IT MAY CONCERN:\",\"main_content\":\"This is to certify that the person whose name, signature, thumb marks and other personal data appearing hereon, has requested for a Barangay Clearance from this Office and the results are listed below.\",\"footer_text\":\"This is to further certify that {resident_name} is a bona fide resident of this Barangay. {resident_name} is known to me with a good moral character, law abiding citizen in the community. {resident_name} has no criminal record found in our Barangay Records.\",\"signature_text\":\"Given this {issued_date}\",\"validity_text\":\"Valid until: {valid_until}\",\"location\":\"Barangay Batia, Bocaue, Bulacan\",\"show_qr_code\":true,\"show_control_number\":true,\"font_family\":\"Times-Roman\",\"font_size\":12}',0,1,NULL,'2025-12-11 19:34:27','2025-12-11 19:34:27','%PDF-1.7\n%\n\n6 0 obj\n<<\n/Filter /FlateDecode\n/Length 112\n>>\nstream\nxœ+är\ná2P\0Á¢t.}Ôœ²Ô’ÌäD]sKsK#…4.éÃeVj¨`j\0D\n!¹\\6¦&ff–æÆFPÒĞÈÀÜÄÌÔÜØÜÂ2s170s63±íB²¸B´¸\\C¸¹\0¹U\nendstream\nendobj\n\n7 0 obj\n<<\n/Filter /FlateDecode\n/Type /ObjStm\n/N 5\n/First 26\n/Length 368\n>>\nstream\nxœÕRßKÃ0~Ï_qúà’¦?ÒÊlk« âØEñ¡kÃ¨ŒDÚTæï]Û9ö >Ûp$w÷İåKïó@€„ \0T„¾„”§`:eüñëC_;İ2~WW-¼\"FÀ\ZŞ_ÚÎ8ğØlÆNØeáŠ½İ±¡<«ÆV]©˜æY¡„Q€	!SÜ—h	šDs2Æ3š\nFÃ˜ò…ğç˜Ë‹ÔPCùõîˆ“Ø üŸ{é®lè!ÿâ“Ì¿·UZ8\réµ2~I…áË%şFÎşßÇõükk~}áÙœi¼4äF“ú)óµnm×”8vÂå3t¸ÕûOíê²¸R\"‰‘§ŠÔØ(şü°}×e%7;¸›#C€b÷ºª‹…= ú®0	\'2†8ğ&Ø	•87Æ:Òf¯JãyÑ¨Ô3âD‹ñM·u½KAñEÑêğ‰-R1¥­j³şT›¹iëc€:~¢®Ç:\nendstream\nendobj\n\n8 0 obj\n<<\n/Size 9\n/Root 2 0 R\n/Info 3 0 R\n/Filter /FlateDecode\n/Type /XRef\n/Length 41\n/W [ 1 2 2 ]\n/Index [ 0 9 ]\n>>\nstream\nxœÄ±\0 ±·Ã-û7ÌÃT	V! ÛlHJN•–8 ŞÏaÇ³\nendstream\nendobj\n\nstartxref\n671\n%%EOF','application/pdf'),(2,'Default Indigency Certificate','indigency_certificate',19,'{\