  `Street_Address` text NOT NULL,
  `Coordinates` point DEFAULT NULL,
  `Head_Resident_ID` varchar(50) DEFAULT NULL,
  `Total_Members` int(11) DEFAULT 1,
  `Household_Type` enum('Nuclear','Extended','Single','Boarding') DEFAULT 'Nuclear',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`Household_ID`),
  UNIQUE KEY `Household_Number` (`Household_Number`),
  KEY `idx_households_sitio` (`Sitio_ID`),
  KEY `idx_households_head` (`Head_Resident_ID`),
  CONSTRAINT `fk_households_head_resident` FOREIGN KEY (`Head_Resident_ID`) REFERENCES `residents` (`Resident_ID`),
  CONSTRAINT `households_ibfk_1` FOREIGN KEY (`Sitio_ID`) REFERENCES `sitios` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
