  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `visitors_host_resident_id_foreign` (`host_resident_id`),
  CONSTRAINT `visitors_host_resident_id_foreign` FOREIGN KEY (`host_resident_id`) REFERENCES `residents` (`Resident_ID`) ON DELETE SET NULL
